CREATE TABLE inspection_work_orders (work_order_id TEXT PRIMARY KEY, procurement_id TEXT NOT NULL, field_project_id TEXT NOT NULL, inspection_date TEXT NOT NULL, production_report_date TEXT NOT NULL, inspection_lag_business_days INTEGER NOT NULL CHECK (inspection_lag_business_days BETWEEN 0 AND 10), work_order_status TEXT NOT NULL CHECK (work_order_status IN ('OPEN','CLOSED','FINALIZED','CANCELLED')), assigned_inspector_id TEXT NOT NULL, assigned_inspector_name TEXT NOT NULL, assigned_project_manager_id TEXT NOT NULL, assigned_project_manager_name TEXT NOT NULL, contractor_name TEXT NOT NULL, created_at TEXT NOT NULL, notes TEXT);

CREATE TABLE inspection_observations (observation_id TEXT PRIMARY KEY, work_order_id TEXT NOT NULL, canonical_sov_item_id TEXT, sov_item_description TEXT NOT NULL, legacy_contractor_cost_code TEXT, observation_type TEXT NOT NULL CHECK (observation_type IN ('COMPLETED_WORK','STORED_MATERIAL','LEGACY_MAPPING_EXCEPTION')), production_date TEXT NOT NULL, observed_quantity_milliunits INTEGER NOT NULL CHECK (observed_quantity_milliunits >= 0), scheduled_value_cents INTEGER NOT NULL CHECK (scheduled_value_cents >= 0), observed_completed_value_cents INTEGER NOT NULL DEFAULT 0 CHECK (observed_completed_value_cents >= 0), stored_material_value_cents INTEGER NOT NULL DEFAULT 0 CHECK (stored_material_value_cents >= 0), acceptance_status TEXT NOT NULL CHECK (acceptance_status IN ('ACCEPTED','CONDITIONAL','REJECTED','UNSUPPORTED','PENDING_REVIEW')), contractor_percent_complete_milli_pct INTEGER, inspector_percent_complete_milli_pct INTEGER, payment_application_id TEXT, uploaded_at TEXT NOT NULL, notes TEXT, FOREIGN KEY (work_order_id) REFERENCES inspection_work_orders(work_order_id));

CREATE TABLE deficiency_cases (deficiency_id TEXT PRIMARY KEY, observation_id TEXT NOT NULL, work_order_id TEXT NOT NULL, deficiency_code TEXT NOT NULL, case_status TEXT NOT NULL CHECK (case_status IN ('OPEN','UNDER_REVIEW','RESOLVED','VOID')), opened_date TEXT NOT NULL, resolved_date TEXT, payment_hold_cents INTEGER NOT NULL DEFAULT 0 CHECK (payment_hold_cents >= 0), description TEXT NOT NULL, FOREIGN KEY (observation_id) REFERENCES inspection_observations(observation_id), FOREIGN KEY (work_order_id) REFERENCES inspection_work_orders(work_order_id));

CREATE TABLE acceptance_decisions (decision_id TEXT PRIMARY KEY, observation_id TEXT NOT NULL, deficiency_id TEXT, reviewer_id TEXT NOT NULL, reviewer_name TEXT NOT NULL, decision_code TEXT NOT NULL CHECK (decision_code IN ('ACCEPTED','CONDITIONAL_ACCEPTANCE','REJECTED','RETURNED_FOR_SUPPORT')), decision_date TEXT NOT NULL, payment_eligible_cents INTEGER NOT NULL DEFAULT 0 CHECK (payment_eligible_cents >= 0), rationale TEXT NOT NULL, FOREIGN KEY (observation_id) REFERENCES inspection_observations(observation_id), FOREIGN KEY (deficiency_id) REFERENCES deficiency_cases(deficiency_id));